/** 更新完成后恢复到更新前页面的一次性路由标记。 */
export const UPDATE_RETURN_ROUTE_KEY = 'money-app-update-return-route'

function isValidRoute(value: string): boolean {
  return value.startsWith('/') && !value.startsWith('//') && !/[\u0000-\u001f\u007f]/.test(value)
}

export function rememberUpdateReturnRoute(fullPath: string): void {
  if (!isValidRoute(fullPath)) return
  localStorage.setItem(UPDATE_RETURN_ROUTE_KEY, fullPath)
}

/** 普通刷新/原生 WebView 重载前的兜底记录，不覆盖更新流程已写入的目标路由。 */
export function rememberCurrentHashRoute(): void {
  if (localStorage.getItem(UPDATE_RETURN_ROUTE_KEY)) return
  const hash = window.location.hash
  const fullPath = hash.startsWith('#') && hash.length > 1 ? hash.slice(1) : '/'
  rememberUpdateReturnRoute(fullPath)
}

/**
 * 在创建 hash router 前消费标记，避免更新 reload 后先落到首页再跳转造成闪烁。
 */
export function restoreUpdateReturnRoute(): string | null {
  const target = localStorage.getItem(UPDATE_RETURN_ROUTE_KEY)
  if (!target) return null
  localStorage.removeItem(UPDATE_RETURN_ROUTE_KEY)
  if (!isValidRoute(target)) return null
  window.history.replaceState(null, '', `#${target}`)
  return target
}
