import { onBeforeUnmount, watch, type Ref } from 'vue'

/**
 * 全局浮层（弹窗/选择器）返回栈。
 * 安卓返回手势（屏幕边缘侧滑）默认直接后退页面路由；页面里有弹窗打开时，
 * 应该先关闭最上层弹窗、再返回上一页——这里把每个打开浮层的 close 回调压栈，
 * main.ts 的 backButton 监听优先消费栈顶。
 */
const stack: Array<() => void> = []

/** 关闭最上层浮层。有浮层被关闭返回 true（本次返回手势到此为止），无浮层返回 false。 */
export function closeTopOverlay(): boolean {
  const close = stack.at(-1)
  if (!close) return false
  close()
  return true
}

/** 浮层组件用：open 变 true 时压栈，变 false / 组件卸载时出栈。 */
export function useOverlayBackClose(open: Ref<boolean>, close: () => void): void {
  watch(open, (value) => {
    if (value) stack.push(close)
    else {
      const index = stack.lastIndexOf(close)
      if (index >= 0) stack.splice(index, 1)
    }
  }, { immediate: true })
  onBeforeUnmount(() => {
    const index = stack.lastIndexOf(close)
    if (index >= 0) stack.splice(index, 1)
  })
}
