import { Capacitor, registerPlugin } from '@capacitor/core'
import { CapacitorUpdater } from '@capgo/capacitor-updater'
import { rememberCurrentHashRoute } from '@/app/update-return-route'
import type { UpdateDecision } from './release-manifest'

interface NativeAppInstallerPlugin {
  downloadAndInstall(options: { url: string; sha256: string; fileName: string }): Promise<void>
  download(options: { url: string; sha256: string; fileName: string }): Promise<void>
  install(options: { fileName: string; sha256: string }): Promise<void>
  /** 通知 Java 层立刻中止当前下载/不调起安装器（V1.0.23 用户放弃语义） */
  cancel(): Promise<void>
  /** 清空已下载的 APK 缓存文件 */
  clearCache(): Promise<void>
}

const NativeAppInstaller = registerPlugin<NativeAppInstallerPlugin>('NativeAppInstaller')

export type UpdatePhase = 'connecting' | 'checking' | 'discovered' | 'downloading' | 'success'

export interface ApplyUpdateOptions {
  /** 阶段切换回调（弹窗驱动进度展示） */
  onPhase?: (phase: UpdatePhase) => void
  /** 下载百分比回调（0-100，仅 bundle 真实进度；PWA/APK 因底层限制可能不触发） */
  onProgress?: (percent: number) => void
  /** 取消信号：检查阶段触发会立即中断；下载中触发会跳过切换/安装步骤（底层下载视平台能力继续或中断） */
  signal?: AbortSignal
  /** 下载并校验完成后、最终切换资源或调起安装器前执行（用于授权台账复查） */
  beforeCommit?: () => Promise<void>
}

export type ApplyUpdateResult =
  | { status: 'success' }
  | { status: 'cancelled' }
  | { status: 'failed'; error: Error }

/** 应用启动时注册：原生平台通知 capgo 当前版本就绪；网页平台注册 Service Worker。 */
export async function initializeOfflineRuntime(): Promise<void> {
  if (Capacitor.isNativePlatform()) {
    await CapacitorUpdater.notifyAppReady()
    return
  }
  // file:// 协议（离线网页版单文件）没有 Service Worker 可言，直接跳过
  if (location.protocol === 'file:') return
  if (!('serviceWorker' in navigator)) return
  const existing = await navigator.serviceWorker.getRegistration()
  // 相对路径：兼容 GitHub Pages 等子路径部署（如 /moneyapp-web/sw.js）
  if (!existing) await navigator.serviceWorker.register('./sw.js')
}

/** 判断是否已被取消（含 throw 安全：避免取消后再走主流程） */
function isCancelled(signal?: AbortSignal): boolean {
  return Boolean(signal?.aborted)
}

/** 等待激活中的 Service Worker 并 reload。跳过 SKIP_WAITING 即放弃本次激活。 */
async function activateWaitingServiceWorker(signal?: AbortSignal, beforeCommit?: () => Promise<void>, onPhase?: (phase: UpdatePhase) => void): Promise<{ status: 'success' | 'cancelled' }> {
  if (!('serviceWorker' in navigator)) throw new Error('当前浏览器不支持离线更新')
  // 发现新版本后立即进入下载阶段：后续所有联网动作（SW 清单检查、新资源下载）都属于"下载中"，
  // 不能停在"发现新版本"等 registration.update() 的网络请求（国内访问慢时卡很久，V1.0.31 修复）。
  // 浏览器不提供 SW 下载的真实百分比（平台限制），弹窗显示无进度的"下载中…"。
  onPhase?.('downloading')
  const registration = await navigator.serviceWorker.getRegistration() ?? await navigator.serviceWorker.register('./sw.js')
  await registration.update()
  if (isCancelled(signal)) return { status: 'cancelled' }
  let worker = registration.waiting ?? registration.installing
  if (worker?.state === 'installing') {
    await new Promise<void>((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error('新版本准备超时')), 30_000)
      const onAbort = () => { clearTimeout(timeout); reject(new Error('已取消')) }
      if (signal) signal.addEventListener('abort', onAbort, { once: true })
      worker?.addEventListener('statechange', () => {
        if (worker?.state === 'installed') { clearTimeout(timeout); if (signal) signal.removeEventListener('abort', onAbort); resolve() }
        if (worker?.state === 'redundant') { clearTimeout(timeout); if (signal) signal.removeEventListener('abort', onAbort); reject(new Error('新版本安装失败')) }
      })
    }).catch((cause) => { if (cause instanceof Error && cause.message === '已取消') return undefined; throw cause })
    worker = registration.waiting
  }
  if (!worker) return { status: 'cancelled' }
  if (isCancelled(signal)) return { status: 'cancelled' }
  onPhase?.('success')
  await beforeCommit?.()
  if (isCancelled(signal)) return { status: 'cancelled' }
  const changed = new Promise<void>((resolve) => {
    const timeout = setTimeout(resolve, 8_000)
    navigator.serviceWorker.addEventListener('controllerchange', () => { clearTimeout(timeout); resolve() }, { once: true })
  })
  worker.postMessage({ type: 'SKIP_WAITING' })
  await changed
  // controllerchange 触发瞬间立即 reload，iOS PWA（WebKit）会偶发产出一个"事件失灵"的假死页面
  // （点击底部导航/链接均无反应，重新打开才恢复，V1.0.29 用户实测报告）。
  // 延迟一拍再刷新，避开 SW 接管与页面重载的竞态窗口（社区通用解法，250ms 用户无感）。
  await new Promise((resolveDelay) => setTimeout(resolveDelay, 250))
  rememberCurrentHashRoute()
  window.location.reload()
  return { status: 'success' }
}

/**
 * 主入口：根据 decision.kind 分派到 PWA / 热更新 / APK 三种更新通道。
 * 每种 kind 都通过 options.onPhase/onProgress 回报进度，便于弹窗驱动 UI。
 * 返回结构化结果：success / cancelled / failed，调用方据此更新弹窗或后续处理。
 */
export async function applyUpdate(
  decision: Exclude<UpdateDecision, { kind: 'current' }>,
  options: ApplyUpdateOptions = {},
): Promise<ApplyUpdateResult> {
  try {
    if (decision.kind === 'pwa') {
      const result = await activateWaitingServiceWorker(options.signal, options.beforeCommit, options.onPhase)
      return { status: result.status }
    }
    if (decision.kind === 'bundle') {
      options.onPhase?.('downloading')
      // 监听 capgo 下载进度（精确百分比，仅 bundle 可用）
      const handle = await CapacitorUpdater.addListener('download', (state) => {
        if (typeof state.percent === 'number') options.onProgress?.(state.percent)
      })
      try {
        if (isCancelled(options.signal)) return { status: 'cancelled' }
        const bundle = await CapacitorUpdater.download({
          url: decision.artifact.url,
          version: decision.manifest.bundleVersion,
          checksum: decision.artifact.sha256,
        })
        if (isCancelled(options.signal)) {
          // capgo 没有 abort API；下载完成后清理已落地的 bundle 文件（V1.0.23 用户放弃语义：不留残留）
          await CapacitorUpdater.delete({ id: bundle.id }).catch(() => undefined)
          return { status: 'cancelled' }
        }
        options.onPhase?.('success')
        await options.beforeCommit?.()
        if (isCancelled(options.signal)) {
          await CapacitorUpdater.delete({ id: bundle.id }).catch(() => undefined)
          return { status: 'cancelled' }
        }
        await CapacitorUpdater.next({ id: bundle.id })
        rememberCurrentHashRoute()
        await CapacitorUpdater.reload()
        return { status: 'success' }
      } finally {
        await handle.remove()
      }
    }
    // apk：先由原生层下载并校验，授权复查后再调起系统安装器
    options.onPhase?.('downloading')
    if (isCancelled(options.signal)) return { status: 'cancelled' }
    // 注册 abort 监听：信号触发立刻通知 Java 端，让下载循环中止、不调起系统安装器
    const onAbort = () => {
      NativeAppInstaller.cancel().catch(() => undefined)
    }
    options.signal?.addEventListener('abort', onAbort, { once: true })
    try {
      const fileName = `money-app-${decision.manifest.productVersion}.apk`
      await NativeAppInstaller.download({
        url: decision.artifact.url,
        sha256: decision.artifact.sha256,
        fileName,
      })
      if (isCancelled(options.signal)) {
        await NativeAppInstaller.clearCache().catch(() => undefined)
        return { status: 'cancelled' }
      }
      options.onPhase?.('success')
      await options.beforeCommit?.()
      if (isCancelled(options.signal)) {
        await NativeAppInstaller.clearCache().catch(() => undefined)
        return { status: 'cancelled' }
      }
      rememberCurrentHashRoute()
      await NativeAppInstaller.install({ fileName, sha256: decision.artifact.sha256 })
      return { status: 'success' }
    } catch (cause) {
      if (cause instanceof Error && cause.message === '已取消') {
        // Java 层识别到取消信号后拒绝 install；清理已下载的 APK 文件不留残留
        await NativeAppInstaller.clearCache().catch(() => undefined)
        return { status: 'cancelled' }
      }
      throw cause
    } finally {
      options.signal?.removeEventListener('abort', onAbort)
    }
  } catch (cause) {
    if (cause instanceof Error && cause.message === '已取消') return { status: 'cancelled' }
    return { status: 'failed', error: cause instanceof Error ? cause : new Error(String(cause)) }
  }
}
