import { createApp } from 'vue'
import { createPinia } from 'pinia'
import { Capacitor } from '@capacitor/core'
import { App as CapacitorApp } from '@capacitor/app'
import App from './App.vue'
import { createAppRouter } from './app/router'
import './styles/global.css'
import { initializeOfflineRuntime } from '@/infrastructure/updater/offline-runtime'
import { closeTopOverlay } from '@/ui/overlay-back-stack'
import { useAppStore } from '@/stores/app-store'
import { rememberCurrentHashRoute } from '@/app/update-return-route'

// 原生 WebView 的重载/进程回收有时不会保留 hash；每次页面卸载前兜底记住当前页面。
// 更新流程已写入目标路由时，rememberCurrentHashRoute 会保持更新目标不被覆盖。
function rememberRouteBeforePageUnload(): void {
  rememberCurrentHashRoute()
}

window.addEventListener('pagehide', rememberRouteBeforePageUnload)
window.addEventListener('beforeunload', rememberRouteBeforePageUnload)

const app = createApp(App)
const router = createAppRouter()
const pinia = createPinia()
app.use(pinia)
app.use(router)
app.mount('#app')

// 安卓返回手势（屏幕边缘侧滑）/返回键的统一规则：
// - 页面里有弹窗/选择器打开：先关闭最上层浮层，本次返回不后退页面。
// - 二级页面：与页面左上角返回按钮一致，按历史后退；无历史时兜底回首页。
// - 其余一级页面（全部流水/报表/设置）：直接回到首页。
// - 首页：2 秒内连续第二次返回才退出 App，第一次给出提示。
// 不能依赖原生 WebView 的 canGoBack 判断——热更新重载后它与页面路由历史会脱节，导致二级页面误退出。
if (Capacitor.isNativePlatform()) {
  let lastBackPressAt = 0
  CapacitorApp.addListener('backButton', () => {
    if (closeTopOverlay()) return
    if (router.currentRoute.value.meta.primary) {
      if (router.currentRoute.value.name === 'home') {
        if (Date.now() - lastBackPressAt < 2000) { CapacitorApp.exitApp(); return }
        lastBackPressAt = Date.now()
        useAppStore(pinia).notify('再按一次退出应用')
        return
      }
      router.replace('/')
      return
    }
    if (window.history.state?.back != null) router.back()
    else router.replace('/')
  })
}

initializeOfflineRuntime().catch((error) => {
  console.error('离线运行时初始化失败', error)
})
