<script setup lang="ts">
import { computed, onMounted } from 'vue'
import { ChevronLeft, DatabaseZap, LoaderCircle } from '@lucide/vue'
import { useRoute, useRouter } from 'vue-router'
import AppBottomNav from '@/components/AppBottomNav.vue'
import AppToast from '@/components/AppToast.vue'
import { useAppStore } from '@/stores/app-store'
import { Capacitor } from '@capacitor/core'

const route = useRoute()
const router = useRouter()
const store = useAppStore()
const title = computed(() => String(route.meta.title ?? '抽屉账本'))
const hideChrome = computed(() => Boolean(route.meta.hideChrome))
/** 页面自带标题栏中间内容（如报表页的日期选择器）时隐藏默认标题，把中间列让给页面 Teleport */
const topbarCenter = computed(() => Boolean(route.meta.topbarCenter))
const showBack = computed(() => !route.meta.primary && !hideChrome.value)
const showNav = computed(() => Boolean(route.meta.primary) && !hideChrome.value)

/**
 * 顶栏返回按钮：优先退上一页；没有上一页可退时回首页。
 * 与 main.ts 的手势返回兜底同语义——更新完成自动刷新后 iOS 会丢失
 * 「上一页」记录（history.state），纯 router.back() 会点了没反应（V1.0.27 修复）。
 */
function goBack() {
  if (window.history.state?.back != null) router.back()
  else router.replace('/')
}

onMounted(() => {
  store.initialize()
  // 网页版：申请持久化存储，防止手机空间不足时系统自动清理账本数据
  if (!Capacitor.isNativePlatform() && typeof navigator !== 'undefined' && navigator.storage?.persist) {
    navigator.storage.persist().catch(() => undefined)
  }
})
</script>

<template>
  <div class="app-shell">
    <header v-if="!hideChrome" class="top-bar">
      <button v-if="showBack" class="back-button" type="button" aria-label="返回" @click="goBack()"><ChevronLeft :size="22" /></button>
      <span v-else class="back-placeholder" />
      <h1 v-if="!topbarCenter">{{ title }}</h1>
      <div v-else id="topbar-center" class="topbar-center" />
      <div id="topbar-actions" class="topbar-actions" />
    </header>
    <main v-if="store.loading && !store.initialized" class="state-screen"><LoaderCircle class="spinner" :size="38" /><p>正在打开本地账本…</p></main>
    <main v-else-if="store.error" class="state-screen"><DatabaseZap :size="42" /><h2>本地数据打开失败</h2><p>{{ store.error }}</p><button class="button primary" type="button" @click="store.initialize()">重新尝试</button><p class="error-hint">账本数据仍保存在本机。在备份之前，请不要清除本网站数据或卸载应用，以免账本丢失。</p></main>
    <RouterView v-else />
    <AppBottomNav v-if="showNav" />
    <AppToast />
  </div>
</template>

