import { createRouter, createWebHashHistory, type Router } from 'vue-router'
import { restoreUpdateReturnRoute } from './update-return-route'

/**
 * 判断路由错误是否为「懒加载代码文件失败」（V1.0.40）。
 * 场景：网页版更新完成自动刷新的瞬间，页面可能拿到的还是旧版代码（SW 接管竞态），
 * 而旧版引用的代码文件已被新版覆盖下线（服务器 404 + 本地缓存被清）。
 * 此时点击导航 → 懒加载组件失败 → vue-router 静默中止导航，用户看到「点了没反应」。
 * 浏览器家族文案：WebKit「Importing a module script failed」/ Chrome「Failed to fetch
 * dynamically imported module」/ Firefox「error loading dynamically imported module」。
 */
export function isChunkLoadFailureMessage(message: string): boolean {
  const normalized = message.toLowerCase()
  return normalized.includes('dynamically imported') || normalized.includes('importing a module')
}

/** 自愈标记：防止「刷新后仍是坏页面」时无限循环刷新 */
const ROUTE_SELF_RELOAD_KEY = 'money-app-route-self-reloaded'

export function createAppRouter(): Router {
  restoreUpdateReturnRoute()
  const router = createRouter({
    // 离线网页版以 file:// 协议打开，必须用 hash 路由（路径里有#），否则刷新会找不到页面
    history: createWebHashHistory(),
    routes: [
      { path: '/', name: 'home', component: () => import('@/features/home/HomePage.vue'), meta: { title: '个人记账', primary: true } },
      { path: '/transactions', name: 'transactions', component: () => import('@/features/transactions/TransactionsPage.vue'), meta: { title: '全部流水', primary: true } },
      { path: '/record', name: 'record-new', component: () => import('@/features/transactions/RecordPage.vue'), meta: { title: '新增流水', hideChrome: true } },
      { path: '/record/:id', name: 'record-edit', component: () => import('@/features/transactions/RecordPage.vue'), meta: { title: '编辑流水', hideChrome: true } },
      { path: '/reports', name: 'reports', component: () => import('@/features/reports/ReportsPage.vue'), meta: { title: '报表', primary: true, topbarCenter: true } },
      { path: '/settings', name: 'settings', component: () => import('@/features/settings/SettingsPage.vue'), meta: { title: '设置', primary: true } },
      { path: '/settings/categories', name: 'categories', component: () => import('@/features/categories/CategoriesPage.vue'), meta: { title: '分类管理', topbarCenter: true } },
      { path: '/settings/categories/new', name: 'category-new', component: () => import('@/features/categories/CategoryEditPage.vue'), meta: { title: '添加分类' } },
      { path: '/settings/categories/:id', name: 'category-edit', component: () => import('@/features/categories/CategoryEditPage.vue'), meta: { title: '编辑分类' } },
      { path: '/settings/license', name: 'license', component: () => import('@/features/settings/LicensePage.vue'), meta: { title: '授权码' } },
      { path: '/settings/about', name: 'about', component: () => import('@/features/settings/AboutPage.vue'), meta: { title: '关于我们' } },
      { path: '/settings/backup-reminder', name: 'backup-reminder', component: () => import('@/features/settings/BackupReminderPage.vue'), meta: { title: '备份提醒' } },
      { path: '/:pathMatch(.*)*', redirect: '/' },
    ],
    scrollBehavior: () => ({ top: 0 }),
  })

  // 自愈（V1.0.40）：懒加载组件失败（更新竞态导致代码文件下线）→ 刷新一次拿新版页面。
  // 先把目标路径写进 hash 再刷新，重新打开后直接落在用户想去的页面；
  // sessionStorage 标记防循环（刷新后导航成功即清除）。
  router.onError((error, to) => {
    const message = error instanceof Error ? error.message : String(error)
    if (!isChunkLoadFailureMessage(message)) return
    if (sessionStorage.getItem(ROUTE_SELF_RELOAD_KEY)) return
    sessionStorage.setItem(ROUTE_SELF_RELOAD_KEY, '1')
    const target = to.fullPath.startsWith('/') ? to.fullPath : '/'
    // 必须用 replaceState 改地址：直接赋 location.hash 会触发 hashchange → vue-router 二次导航，
    // 与懒加载失败的模块缓存相互纠缠，把紧随的 reload 挤掉（WebKit 实测复现）；replaceState 静默改 URL。
    // reload 时新 SW 已接管（懒加载失败正是 purge 完成的表现），新 HTML 引用的新文件名必然命中 precache
    window.history.replaceState(null, '', `#${target}`)
    window.location.reload()
  })
  router.afterEach(() => {
    // 任意一次导航成功都说明页面代码健康，清掉自愈标记
    sessionStorage.removeItem(ROUTE_SELF_RELOAD_KEY)
  })

  return router
}
